import{_ as h,C as e,o as d,c as u,j as i,a as l,E as n,a3 as o}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"说卦传","description":"讲八卦作法、卦德、取象与方位的传——从三才六画到先后天秩序，建立理解卦象语言的入口。","frontmatter":{"title":"说卦传","description":"讲八卦作法、卦德、取象与方位的传——从三才六画到先后天秩序，建立理解卦象语言的入口。","category":"guide","aliases":["说卦传","说卦","shuo gua zhuan"],"source":["《周易·说卦传》"]},"headers":[],"relativePath":"yijing/shi-yi/shuo-gua-zhuan.md","filePath":"yijing/shi-yi/shuo-gua-zhuan.md","lastUpdated":1788140575000}'),p={name:"yijing/shi-yi/shuo-gua-zhuan.md"};function c(m,a,g,b,q,f){const t=e("DaoReadingPrelude"),r=e("DaoTextReading"),s=e("DaoKeywordCards");return d(),u("div",null,[a[0]||(a[0]=i("h1",{id:"说卦传",tabindex:"-1"},[l("说卦传 "),i("a",{class:"header-anchor",href:"#说卦传","aria-label":'Permalink to "说卦传"'},"​")],-1)),n(t,{title:"先会其意，再进入万象",summary:"《说卦传》是十翼中专门展开八卦系统的一篇：它说明圣人如何作《易》，天地人三才如何成为六画，八卦如何对应自然、身体、亲属、动物与器物，也呈现先天的对待和后天的流行。它不是一张必须死背的对应表，而是一套从意入象、由象观变的阅读方法。",points:[{label:"先明根",text:"先读圣人作易的步骤，以及阴阳、柔刚、仁义的三才结构。"},{label:"再识象",text:"掌握八卦最核心的卦德：健、顺、动、入、陷、丽、止、说。"},{label:"后会通",text:"再看先天对待、后天流行和广取象，不把象例误当成穷尽。"}],hint:"取象的关键不是遇到任何事都机械查表，而是先问：此刻我取的是哪一种意？同一事物因所取之意不同，可能显出不同的卦象。"}),a[1]||(a[1]=o("",12)),n(r,{colophon:"三才六画 · 先天对待 · 后天流行 · 会意取象",tone:"ink",sections:[{id:"duan-01",sentences:[["昔者圣人之作《易》也，幽赞于神明而生蓍，参天两地而倚数，观变于阴阳而立卦，发挥于刚柔而生爻，和顺于道德而理于义，穷理尽性以至于命。"],["昔者圣人之作《易》也，将以顺性命之理。是以立天之道曰阴与阳，立地之道曰柔与刚，立人之道曰仁与义。"],["兼三才而两之，故《易》六画而成卦。分阴分阳，迭用柔刚，故《易》六位而成章。"]]},{id:"duan-02",sentences:[["天地定位，山泽通气，雷风相薄，水火不相射，八卦相错。"],["数往者顺，知来者逆，是故《易》逆数也。"],["雷以动之，风以散之，雨以润之，日以烜之，艮以止之，兑以说之，乾以君之，坤以藏之。"]]},{id:"duan-03",sentences:[["帝出乎震，齐乎巽，相见乎离，致役乎坤，说言乎兑，战乎乾，劳乎坎，成言乎艮。"],["万物出乎震，震东方也。齐乎巽，巽东南也；齐也者，言万物之絜齐也。"],["离也者，明也，万物皆相见，南方之卦也；圣人南面而听天下，向明而治，盖取诸此也。"],["坤也者，地也，万物皆致养焉，故曰致役乎坤。兑，正秋也，万物之所说也，故曰说言乎兑。"],["战乎乾，乾西北之卦也，言阴阳相薄也。坎者水也，正北方之卦也，劳卦也，万物之所归也，故曰劳乎坎。"],["艮，东北之卦也，万物之所成终而成始也，故曰成言乎艮。"]]},{id:"duan-04",sentences:[["神也者，妙万物而为言者也。动万物者莫疾乎雷，挠万物者莫疾乎风，躁万物者莫乎火，说万物者莫说乎泽，润万物者莫润乎水，终万物始万物者莫盛乎艮。"],["故水火相逮，雷风不相悖，山泽通气，然后能变化，既成万物也。"],["乾，健也；坤，顺也；震，动也；巽，入也；坎，陷也；离，丽也；艮，止也；兑，说也。"]]},{id:"duan-05",sentences:[["乾为马，坤为牛，震为龙，巽为鸡，坎为豕，离为雉，艮为狗，兑为羊。"],["乾为首，坤为腹，震为足，巽为股，坎为耳，离为目，艮为手，兑为口。"],["乾，天也，故称乎父；坤，地也，故称乎母。震一索而得男，故谓之长男；巽一索而得女，故谓之长女。"],["坎再索而得男，故谓之中男；离再索而得女，故谓之中女；艮三索而得男，故谓之少男；兑三索而得女，故谓之少女。"]]},{id:"duan-06",sentences:[["乾为天，为圆，为君，为父，为玉，为金，为寒，为冰，为大赤，为良马，为老马，为瘠马，为驳马，为木果。"],["坤为地，为母，为布，为釜，为吝啬，为均，为子母牛，为大舆，为文，为众，为柄，其于地也为黑。"],["震为雷，为龙，为玄黄，为旉，为大途，为长子，为决躁，为苍筤竹，为萑苇；其于马也为善鸣，为馵足，为作足，为的颡；其于稼也为反生，其究为健，为蕃鲜。"],["巽为木，为风，为长女，为绳直，为工，为白，为长，为高，为进退，为不果，为臭；其于人也为寡发，为广颡，为多白眼，为近利市三倍，其究为躁卦。"]]},{id:"duan-07",sentences:[["坎为水，为沟渎，为隐伏，为矫輮，为弓轮；其于人也为加忧，为心病，为耳痛，为血卦，为赤；其于马也为美脊，为亟心，为下首，为薄蹄，为曳；其于舆也为多眚，为通，为月，为盗；其于木也为坚多心。"],["离为火，为日，为电，为中女，为甲胄，为戈兵；其于人也为大腹，为乾卦，为鳖，为蟹，为蠃，为蚌，为龟；其于木也为科上槁。"],["艮为山，为径路，为小石，为门阙，为果蓏，为阍寺，为指，为狗，为鼠，为黔喙之属；其于木也为坚多节。"],["兑为泽，为少女，为巫，为口舌，为毁折，为附决；其于地也为刚卤，为妾，为羊。"]]}],"aria-label":"说卦传原文"}),a[2]||(a[2]=i("blockquote",null,[i("p",null,"注：本页据通行本整理。「艮为手」与后文「艮为指」等文字，在历代传本、注疏和后世易学中有不同讨论；「离为中女」按上下文及通行本校正。取象解释也不等同于经文逐项给出唯一推导。")],-1)),a[3]||(a[3]=i("h2",{id:"【原典层】字词释义",tabindex:"-1"},[l("【原典层】字词释义 "),i("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(s,{items:[{term:"幽赞",pinyin:["yōu","zàn"],meaning:"在幽微处辅助、赞襄神明。放在作《易》的语境中，指对不可尽见的变化保持敬畏，并由此进入蓍筮与象数。"},{term:"三才",pinyin:["sān","cái"],meaning:"天、地、人。天道为阴阳，地道为柔刚，人道为仁义；三才各有两面，重之而成六画。"},{term:"相错",pinyin:["xiāng","cuò"],meaning:"彼此交错、相对配置。先天八卦以乾坤、山泽、雷风、水火等对待关系呈现结构。"},{term:"逆数",pinyin:["nì","shǔ"],meaning:"由已见之象推知未至之事。「数往者顺，知来者逆」说明《易》包含由现在观未来的推演方向。"},{term:"絜齐",pinyin:["jié","qí"],meaning:"整齐、齐一。「齐乎巽」写万物在生长过程中逐渐整饬、成形，而非静止排列。"},{term:"说",pinyin:["tuō"],meaning:"在「兑以说之」「兑，说也」中通「悦」，指和悦、喜悦、使万物舒展。"},{term:"丽",pinyin:["lí"],meaning:"附丽、依附。「离，丽也」不是单指美丽，而是事物有所附着，因依托而明。"},{term:"一索",pinyin:["yī","suǒ"],meaning:"第一次求取、交感。乾坤为父母，三次交感分别生出长、中、少三男三女，是八卦亲属象的生成说明。"},{term:"取象",pinyin:["qǔ","xiàng"],meaning:"从卦德、卦形、功能、关系或经验中取其相似之意。象例不是穷举，关键是会通当前情境中的那个意。"},{term:"先天",pinyin:["xiān","tiān"],meaning:"在本页主要指天地定位、山泽通气等对待结构，偏重空间关系与阴阳相对。"},{term:"后天",pinyin:["hòu","tiān"],meaning:"在本页主要指帝出乎震、成言乎艮的流行次序，偏重时间、方位与万物生长收藏。"},{term:"成终成始",pinyin:["chéng","zhōng","chéng","shǐ"],meaning:"既完成一个周期，又开启下一个周期。「艮」处于后天方位的终始交界，提示结束与开始相接。"}]}),a[4]||(a[4]=o("",42))])}const P=h(p,[["render",c]]);export{y as __pageData,P as default};
